html:
{%- set L = doc.lines or [] -%}
{%- macro sec(name) -%}{{ L | selectattr('section', 'equalto', name) | list }}{%- endmacro -%}
{%- macro rows(name, wcol='Weight') -%}
	{%- set items = L | selectattr('section', 'equalto', name) | list -%}
	{%- if items -%}
	<table class="ds-t"><thead><tr><th>{{ name }}</th><th class="r">Pcs</th><th class="r">{{ wcol }}</th><th class="r">Value</th><th>Note</th></tr></thead><tbody>
	{%- for r in items -%}
	<tr><td>{{ r.label }}</td><td class="r">{{ r.pcs or "" }}</td>
	<td class="r">{{ "%.3f"|format(r.weight) if r.weight else "" }} {{ r.uom }}</td>
	<td class="r">{{ frappe.utils.fmt_money(r.value) if r.value else "" }}</td><td>{{ r.extra or "" }}</td></tr>
	{%- endfor -%}
	</tbody></table>
	{%- else -%}<div class="ds-none">Nothing recorded.</div>{%- endif -%}
{%- endmacro -%}
<style>
.ds{font-family:-apple-system,'Segoe UI',Roboto,Helvetica,sans-serif;color:#1a1a1a;font-size:12px;}
.ds h1{font-size:22px;margin:0;letter-spacing:.3px;}
.ds .ds-date{font-size:15px;color:#555;margin:2px 0 14px;}
.ds h2{font-size:13px;text-transform:uppercase;letter-spacing:.09em;color:#6b7785;border-bottom:1.5px solid #111;padding-bottom:4px;margin:20px 0 8px;}
.ds .tiles{display:flex;flex-wrap:wrap;gap:10px;margin:6px 0 4px;}
.ds .tile{border:1px solid #ccc;border-radius:8px;padding:8px 16px;min-width:130px;}
.ds .tile .k{font-size:9.5px;text-transform:uppercase;letter-spacing:.06em;color:#6b7785;}
.ds .tile .v{font-size:19px;font-weight:800;}
.ds table.ds-t{width:100%;border-collapse:collapse;margin:4px 0 10px;font-size:11.5px;}
.ds table.ds-t th{border:1px solid #999;background:#f0f0f0;padding:4px 8px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.05em;}
.ds table.ds-t td{border:1px solid #bbb;padding:3.5px 8px;}
.ds .r{text-align:right;}
.ds .ds-none{color:#8a949e;font-size:11px;padding:6px 2px;}
.ds .pageno{font-size:9px;color:#9aa6b2;text-align:right;margin-top:8px;}
.ds .brk{page-break-after:always;}
</style>
<div class="ds">

<!-- ============================== PAGE 1 — SCOREBOARD ============================== -->
<h1>{{ frappe.db.get_single_value("Global Defaults", "default_company") or "Jewelima" }} — Day Sheet</h1>
<div class="ds-date">{{ frappe.utils.formatdate(doc.date, "dd MMMM yyyy") }}</div>

<h2>Orders &amp; Floor</h2>
<div class="tiles">
	<div class="tile"><div class="k">Orders placed</div><div class="v">{{ doc.orders_placed }}</div></div>
	<div class="tile"><div class="k">Bags created</div><div class="v">{{ doc.bags_created }}</div></div>
	<div class="tile"><div class="k">Bags cancelled</div><div class="v">{{ doc.bags_cancelled }}</div></div>
	<div class="tile"><div class="k">Bags on floor</div><div class="v">{{ doc.floor_bags }}</div></div>
	<div class="tile"><div class="k">Overdue orders</div><div class="v">{{ doc.overdue_orders }}</div></div>
	<div class="tile"><div class="k">Employees worked</div><div class="v">{{ doc.employees_worked }}</div></div>
</div>

<h2>Material</h2>
<div class="tiles">
	<div class="tile"><div class="k">Gold issued</div><div class="v">{{ "%.3f"|format(doc.gold_issued_g) }} g</div></div>
	<div class="tile"><div class="k">Pure gold issued</div><div class="v">{{ "%.3f"|format(doc.gold_issued_pure_g) }} g</div></div>
	<div class="tile"><div class="k">Stones issued</div><div class="v">{{ doc.stones_issued_pcs }} pcs / {{ "%.3f"|format(doc.stones_issued_ct) }} ct</div></div>
	<div class="tile"><div class="k">Loss booked</div><div class="v">{{ "%.3f"|format(doc.loss_booked_g) }} g</div></div>
</div>

<h2>Output &amp; Sales</h2>
<div class="tiles">
	<div class="tile"><div class="k">Products made</div><div class="v">{{ doc.products_made }}</div></div>
	<div class="tile"><div class="k">Pieces imported</div><div class="v">{{ doc.pieces_imported }}</div></div>
	<div class="tile"><div class="k">Cert sent / received</div><div class="v">{{ doc.cert_sent_pcs }} / {{ doc.cert_received_pcs }}</div></div>
	<div class="tile"><div class="k">Sales</div><div class="v">{{ doc.sales_count }} ({{ doc.sales_pieces }} pcs)</div></div>
	<div class="tile"><div class="k">Sales value</div><div class="v">{{ frappe.utils.fmt_money(doc.sales_value) }}</div></div>
</div>

<h2>Closing Positions</h2>
<div class="tiles">
	<div class="tile"><div class="k">Pure gold (book)</div><div class="v">{{ "%.3f"|format(doc.closing_pure_gold_g) }} g</div></div>
	<div class="tile"><div class="k">Stones (book)</div><div class="v">{{ "%.3f"|format(doc.closing_stones_ct) }} ct</div></div>
</div>
<div class="pageno">Day Sheet {{ doc.date }} — page 1 of 4</div>
<div class="brk"></div>

<!-- ============================== PAGE 2 — ORDERS & BENCH WORK ============================== -->
<h2>Orders by Type</h2>
{{ rows("Orders") }}
<h2>Orders by Karat (colour ignored)</h2>
{{ rows("Orders by Karat") }}
<h2>Bench Work (done / grams worked; issued in note)</h2>
{{ rows("Bench Work") }}
<h2>Top Employees of the Day</h2>
{{ rows("Top Employees") }}
<div class="pageno">Day Sheet {{ doc.date }} — page 2 of 4</div>
<div class="brk"></div>

<!-- ============================== PAGE 3 — ISSUES & LOSS ============================== -->
<h2>Gold Issued</h2>
{{ rows("Gold Issued") }}
<h2>Stones Issued</h2>
{{ rows("Stones Issued") }}
<h2>Issued By</h2>
{{ rows("Issued By") }}
<h2>Loss Booked (per bench)</h2>
{{ rows("Loss") }}
<h2>Purchases into Stock</h2>
{{ rows("Purchases") }}
<div class="pageno">Day Sheet {{ doc.date }} — page 3 of 4</div>
<div class="brk"></div>

<!-- ============================== PAGE 4 — SALES, CERTIFICATION, CLOSING ============================== -->
<h2>Sales</h2>
{{ rows("Sales") }}
<h2>Certification</h2>
{{ rows("Certification") }}
<h2>Ownership / Reservation Changes</h2>
{{ rows("Ownership") }}
<h2>Closing Stock</h2>
{{ rows("Closing Stock") }}
<div class="pageno">Day Sheet {{ doc.date }} — page 4 of 4 · sealed {{ frappe.utils.format_datetime(doc.creation) }}</div>
</div>
